use std::io::{self, Read, Write};

struct Node {
    key: i64,
    left: Tree,
    right: Tree,
}

type Tree = Option<Box<Node>>;

fn insert(t: &mut Tree, x: i64) -> bool {
    if t.is_none() {
        *t = Some(Box::new(Node { key: x, left: None, right: None }));
        return true;
    }
    let n = t.as_mut().unwrap();
    if x < n.key {
        insert(&mut n.left, x)
    } else if x > n.key {
        insert(&mut n.right, x)
    } else {
        false
    }
}

fn contains(t: &Tree, x: i64) -> bool {
    let mut cur = t;
    while let Some(n) = cur {
        if x == n.key {
            return true;
        }
        cur = if x < n.key { &n.left } else { &n.right };
    }
    false
}

// Removes the minimum key of a non-empty subtree and returns it.
fn take_min(t: &mut Tree) -> i64 {
    if t.as_ref().unwrap().left.is_some() {
        return take_min(&mut t.as_mut().unwrap().left);
    }
    let n = t.take().unwrap();
    *t = n.right;
    n.key
}

fn delete(t: &mut Tree, x: i64) -> bool {
    let n = match t.as_mut() {
        None => return false,
        Some(n) => n,
    };
    if x < n.key {
        return delete(&mut n.left, x);
    }
    if x > n.key {
        return delete(&mut n.right, x);
    }
    let l = n.left.take();
    let r = n.right.take();
    *t = match (l, r) {
        (None, None) => None,
        (Some(l), None) => Some(l),
        (None, Some(r)) => Some(r),
        (Some(l), Some(r)) => {
            let mut r = Some(r);
            let s = take_min(&mut r);
            Some(Box::new(Node { key: s, left: Some(l), right: r }))
        }
    };
    true
}

fn height(t: &Tree) -> usize {
    match t {
        None => 0,
        Some(n) => 1 + height(&n.left).max(height(&n.right)),
    }
}

fn inorder(t: &Tree, out: &mut Vec<i64>) {
    if let Some(n) = t {
        inorder(&n.left, out);
        out.push(n.key);
        inorder(&n.right, out);
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut out = String::new();
    let mut tree: Tree = None;

    for line in input.lines() {
        let mut parts = line.split_whitespace();
        let cmd = match parts.next() {
            Some(c) => c,
            None => continue,
        };
        let arg = parts.next().and_then(|s| s.parse::<i64>().ok());
        match (cmd, arg) {
            ("insert", Some(x)) => {
                out.push_str(if insert(&mut tree, x) { "ok\n" } else { "dup\n" });
            }
            ("contains", Some(x)) => {
                out.push_str(if contains(&tree, x) { "yes\n" } else { "no\n" });
            }
            ("delete", Some(x)) => {
                out.push_str(if delete(&mut tree, x) { "ok\n" } else { "missing\n" });
            }
            ("inorder", _) => {
                let mut keys = Vec::new();
                inorder(&tree, &mut keys);
                if keys.is_empty() {
                    out.push_str("<empty>\n");
                } else {
                    let s: Vec<String> = keys.iter().map(|k| k.to_string()).collect();
                    out.push_str(&s.join(" "));
                    out.push('\n');
                }
            }
            ("height", _) => {
                out.push_str(&format!("{}\n", height(&tree)));
            }
            ("min", _) => {
                let mut cur = &tree;
                let mut res = None;
                while let Some(n) = cur {
                    res = Some(n.key);
                    cur = &n.left;
                }
                match res {
                    Some(k) => out.push_str(&format!("{}\n", k)),
                    None => out.push_str("empty\n"),
                }
            }
            ("max", _) => {
                let mut cur = &tree;
                let mut res = None;
                while let Some(n) = cur {
                    res = Some(n.key);
                    cur = &n.right;
                }
                match res {
                    Some(k) => out.push_str(&format!("{}\n", k)),
                    None => out.push_str("empty\n"),
                }
            }
            _ => {}
        }
    }

    io::stdout().write_all(out.as_bytes()).unwrap();
}
